12	export function filterReleaseGroups(
13	  projectGraph: ProjectGraph,
14	  nxReleaseConfig: NxReleaseConfig,
15	  projectsFilter?: string[],
16	  groupsFilter?: string[]
17	): {
18	  error: null | { title: string; bodyLines?: string[] };
19	  releaseGroups: ReleaseGroupWithName[];
20	  releaseGroupToFilteredProjects: Map<ReleaseGroupWithName, Set<string>>;
21	} {
22	  let releaseGroups: ReleaseGroupWithName[] = Object.entries(
23	    nxReleaseConfig.groups
24	  ).map(([name, group]) => {
25	    return {
26	      ...group,
27	      name,
28	      resolvedVersionPlans: group.versionPlans ? [] : false,
29	    };
30	  });
31	
32	  const filteredProjectToReleaseGroup = new Map<string, ReleaseGroupWithName>();
33	  const releaseGroupToFilteredProjects = new Map<
34	    ReleaseGroupWithName,
35	    Set<string>
36	  >();
37	
38	  for (const releaseGroup of releaseGroups) {
39	    for (const project of releaseGroup.projects) {
40	      filteredProjectToReleaseGroup.set(project, releaseGroup);
41	      if (!releaseGroupToFilteredProjects.has(releaseGroup)) {
42	        releaseGroupToFilteredProjects.set(releaseGroup, new Set());
43	      }
44	      releaseGroupToFilteredProjects.get(releaseGroup).add(project);
45	    }
46	  }
47	
48	  /**
49	   * User is filtering to a subset of projects. We need to make sure that what they have provided can be reconciled
50	   * against their configuration in terms of release groups.
51	   */
52	  if (projectsFilter?.length) {
53	    const matchingProjectsForFilter = findMatchingProjects(
54	      projectsFilter,
55	      projectGraph.nodes
56	    );
57	
58	    if (!matchingProjectsForFilter.length) {
59	      return {
60	        error: {
61	          title: `Your --projects filter "${projectsFilter}" did not match any projects in the workspace`,
62	        },
63	        releaseGroups: [],
64	        releaseGroupToFilteredProjects,
65	      };
66	    }
67	
68	    // Remove any non-matching projects from filteredProjectToReleaseGroup
69	    for (const project of filteredProjectToReleaseGroup.keys()) {
70	      if (!matchingProjectsForFilter.includes(project)) {
71	        filteredProjectToReleaseGroup.delete(project);
72	      }
73	    }
74	
75	    // Filter out any non-matching projects from the release group to filtered projects map
76	    for (const releaseGroup of releaseGroups) {
77	      releaseGroup.projects
78	        .filter((p) => !matchingProjectsForFilter.includes(p))
79	        .forEach((p) =>
80	          releaseGroupToFilteredProjects.get(releaseGroup).delete(p)
81	        );
82	    }
83	
84	    /**
85	     * If there are release groups specified, each filtered project must match at least one release
86	     * group, otherwise the command + config combination is invalid.
87	     */
88	    if (releaseGroups.length) {
89	      const unmatchedProjects = matchingProjectsForFilter.filter(
90	        (p) => !filteredProjectToReleaseGroup.has(p)
91	      );
92	      if (unmatchedProjects.length) {
93	        return {
94	          error: {
95	            title: `The following projects which match your projects filter "${projectsFilter}" did not match any configured release groups:`,
96	            bodyLines: unmatchedProjects.map((p) => `- ${p}`),
97	          },
98	          releaseGroups: [],
99	          releaseGroupToFilteredProjects,
100	        };
101	      }
102	    }
103	
104	    /**
105	     * If the user is filtering to a subset of projects, we need to make sure that they are all within release groups
106	     * with "independent" configured for their projectsRelationship. If not, the filtering is invalid, and they should instead
107	     * be targeting the release groups directly using the --group flag, or they should update their configuration to
108	     * make the projects they were trying to filter be independently releasable.
109	     */
110	    const releaseGroupsForFilteredProjects = Array.from(
111	      new Set(Array.from(filteredProjectToReleaseGroup.values()))
112	    );
113	    const releaseGroupsThatAreNotIndependent =
114	      releaseGroupsForFilteredProjects.filter(
115	        (rg) => rg.projectsRelationship !== 'independent'
116	      );
117	    if (releaseGroupsThatAreNotIndependent.length) {
118	      // Special handling for IMPLICIT_DEFAULT_RELEASE_GROUP
119	      if (
120	        releaseGroupsThatAreNotIndependent.length === 1 &&
121	        releaseGroupsThatAreNotIndependent[0].name ===
122	          IMPLICIT_DEFAULT_RELEASE_GROUP
123	      ) {
124	        return {
125	          error: {
126	            title: `In order to release specific projects independently with --projects those projects must be configured appropriately. For example, by setting \`"projectsRelationship": "independent"\` in your nx.json config.`,
127	            bodyLines: [],
128	          },
129	          releaseGroups: [],
130	          releaseGroupToFilteredProjects,
131	        };
132	      }
133	
134	      return {
135	        error: {
136	          title: `Your --projects filter "${projectsFilter}" matched projects in the following release groups which do not have "independent" configured for their "projectsRelationship":`,
137	          bodyLines: releaseGroupsThatAreNotIndependent.map(
138	            (rg) => `- ${rg.name}`
139	          ),
140	        },
141	        releaseGroups: [],
142	        releaseGroupToFilteredProjects,
143	      };
144	    }
145	
146	    output.note({
147	      title: `Your filter "${projectsFilter}" matched the following projects:`,
148	      bodyLines: matchingProjectsForFilter.map((p) => {
149	        const releaseGroupForProject = filteredProjectToReleaseGroup.get(p);
150	        if (releaseGroupForProject.name === IMPLICIT_DEFAULT_RELEASE_GROUP) {
151	          return `- ${p}`;
152	        }
153	        return `- ${p} (release group "${releaseGroupForProject.name}")`;
154	      }),
155	    });
156	
157	    // Filter the releaseGroups collection appropriately
158	    for (const [
159	      releaseGroupWithName,
160	      matchingProjects,
161	    ] of releaseGroupToFilteredProjects.entries()) {
162	      if (matchingProjects.size === 0) {
163	        releaseGroupToFilteredProjects.delete(releaseGroupWithName);
164	      }
165	    }
166	    releaseGroups = releaseGroups.filter(
167	      (rg) => releaseGroupToFilteredProjects.get(rg)?.size > 0
168	    );
169	
170	    return {
171	      error: null,
172	      releaseGroups,
173	      releaseGroupToFilteredProjects,
174	    };
175	  }
176	
177	  /**
178	   * The user is filtering by release group
179	   */
180	  if (groupsFilter?.length) {
181	    releaseGroups
182	      .filter((g) => !groupsFilter.includes(g.name))
183	      .forEach((g) => releaseGroupToFilteredProjects.delete(g));
184	    releaseGroups = releaseGroups.filter((g) => groupsFilter.includes(g.name));
185	  }
186	
187	  if (!releaseGroups.length) {
188	    return {
189	      error: {
190	        title: groupsFilter
191	          ? `Your --groups filter "${groupsFilter}" did not match any release groups in the workspace`
