+      },
+      filterLog: null,
+      releaseGroups: [],
+      releaseGroupToFilteredProjects,
+    };
+  }
+
+  return {
+    error: null,
+    filterLog,
+    releaseGroups,
+    releaseGroupToFilteredProjects,
+  };
+}
