+    | 'INVALID_CHANGELOG_CREATE_RELEASE_API_BASE_URL'
+    | 'DOCKER_VERSION_SCHEME_USES_VERSION_ACTIONS_VERSION_WHEN_SKIP_VERSION_ACTIONS'
+    | 'GIT_PUSH_FALSE_WITH_CREATE_RELEASE'
